<h4 class="mb-3">Stock Movements</h4>
<form class="row g-2 mb-3" method="get"><input type="hidden" name="r" value="stock/movements"><div class="col-md-2"><input type="date" class="form-control" name="from" value="<?= e($from) ?>"></div><div class="col-md-2"><input type="date" class="form-control" name="to" value="<?= e($to) ?>"></div>
<div class="col-md-3"><select class="form-select" name="warehouse"><option value="">All warehouses</option><?php foreach ($warehouses as $w): ?><option value="<?= (int)$w['id'] ?>" <?= input('warehouse') == $w['id'] ? 'selected' : '' ?>><?= e($w['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><select class="form-select" name="type"><option value="">All types</option><?php foreach ($types as $t): ?><option <?= input('type') === $t ? 'selected' : '' ?>><?= e($t) ?></option><?php endforeach; ?></select></div><div class="col-auto"><button class="btn btn-outline-secondary">Filter</button></div></form>
<div class="card"><div class="table-responsive"><table class="table table-sm mb-0 small"><thead class="table-light"><tr><th>Date</th><th>Product</th><th>Warehouse</th><th>Type</th><th class="text-end">Change</th><th>Ref</th><th>Note</th><th>User</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['created_at']) ?></td><td><?= link_product($r['product_id'], $r['sku'] . ' ' . $r['name']) ?></td><td><?= link_wh($r['warehouse_id'], $r['warehouse']) ?></td><td><?= e($r['type']) ?></td><td class="text-end <?= $r['qty_change'] > 0 ? 'text-success' : 'text-danger' ?>"><?= $r['qty_change'] > 0 ? '+' : '' ?><?= fq($r['qty_change']) ?></td><td><?= e($r['ref_type'] . ($r['ref_id'] ? '#' . $r['ref_id'] : '')) ?></td><td><?= e($r['note']) ?></td><td><?= e($r['username']) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="8" class="text-center text-muted py-3">No movements.</td></tr><?php endif; ?></tbody></table></div></div>
